local a=""
local payload = a
local env = (type(getgenv) == "function" and getgenv()) or _G
if env.VexHUB_BootRunning then
    warn("[VexHUB] Startup is already running.")
    return
end
if type(env.VexHUB_BootCleanup) == "function" then
    pcall(env.VexHUB_BootCleanup)
end
env.VexHUB_BootRunning = true

local screen, group, status, percent, fill, closeButton
local progressTween
local function cleanup()
    if progressTween then pcall(function() progressTween:Cancel() end) end
    if screen then screen:Destroy() end
    env.VexHUB_BootRunning = false
    if env.VexHUB_BootCleanup == cleanup then env.VexHUB_BootCleanup = nil end
end
env.VexHUB_BootCleanup = cleanup

local ok, failure = pcall(function()
    local Players = game:GetService("Players")
    local TweenService = game:GetService("TweenService")
    local player = Players.LocalPlayer
    local deadline = os.clock() + 30
    while not player and os.clock() < deadline do
        task.wait(0.1)
        player = Players.LocalPlayer
    end
    assert(player, "LocalPlayer is unavailable.")
    local playerGui = assert(player:WaitForChild("PlayerGui", 15),
        "PlayerGui is unavailable.")
    if type(env.CB_Cleanup) == "function" then pcall(env.CB_Cleanup) end

    local function make(class, properties, parent)
        local object = Instance.new(class)
        for key, value in pairs(properties) do object[key] = value end
        object.Parent = parent
        return object
    end
    local function round(parent, radius)
        make("UICorner", {CornerRadius = UDim.new(0, radius)}, parent)
    end
    local function text(value, x, y, width, height, size, color)
        return make("TextLabel", {
            Position = UDim2.fromOffset(x, y),
            Size = UDim2.fromOffset(width, height),
            BackgroundTransparency = 1,
            Text = value,
            TextColor3 = color,
            Font = Enum.Font.Gotham,
            TextSize = size,
            TextXAlignment = Enum.TextXAlignment.Left,
        }, group)
    end

    screen = make("ScreenGui", {
        Name = "VexHUB_Loading",
        ResetOnSpawn = false,
        IgnoreGuiInset = true,
        DisplayOrder = 250,
        ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
    }, playerGui)
    group = make("CanvasGroup", {
        Position = UDim2.fromScale(0.5, 0.5),
        AnchorPoint = Vector2.new(0.5, 0.5),
        Size = UDim2.fromOffset(380, 238),
        BackgroundColor3 = Color3.fromRGB(17, 19, 30),
        BorderSizePixel = 0,
        GroupTransparency = 0,
    }, screen)
    round(group, 16)
    local camera = workspace.CurrentCamera
    local viewport = camera and camera.ViewportSize
    local scale = viewport and math.min(1, (viewport.X - 24) / 380,
        (viewport.Y - 24) / 238) or 1
    make("UIScale", {Scale = math.max(0.35, scale)}, group)
    make("UIStroke", {
        Color = Color3.fromRGB(109, 88, 164),
        Transparency = 0.25,
        Thickness = 1,
    }, group)

    local logo = make("Frame", {
        Position = UDim2.fromOffset(24, 24),
        Size = UDim2.fromOffset(44, 44),
        BackgroundColor3 = Color3.fromRGB(80, 57, 137),
        BorderSizePixel = 0,
    }, group)
    round(logo, 12)
    make("TextLabel", {
        Size = UDim2.fromScale(1, 1),
        BackgroundTransparency = 1,
        Text = "V",
        TextColor3 = Color3.fromRGB(246, 241, 255),
        Font = Enum.Font.GothamBold,
        TextSize = 29,
    }, logo)
    local title = text("VexHUB", 82, 23, 230, 30, 26,
        Color3.fromRGB(235, 226, 255))
    title.Font = Enum.Font.GothamBold
    text("COUNTER BLOX / ULTIMATE", 84, 56, 272, 16, 10,
        Color3.fromRGB(143, 154, 184))
    text("Preparing your workspace", 24, 96, 320, 22, 15,
        Color3.fromRGB(219, 226, 244))
    status = text("Starting...", 24, 126, 290, 20, 12,
        Color3.fromRGB(151, 164, 194))
    percent = text("0%", 320, 126, 36, 20, 12,
        Color3.fromRGB(184, 166, 255))
    percent.TextXAlignment = Enum.TextXAlignment.Right

    local track = make("Frame", {
        Position = UDim2.fromOffset(24, 162),
        Size = UDim2.fromOffset(332, 7),
        BackgroundColor3 = Color3.fromRGB(40, 43, 62),
        BorderSizePixel = 0,
        ClipsDescendants = true,
    }, group)
    round(track, 4)
    fill = make("Frame", {
        Size = UDim2.fromScale(0, 1),
        BackgroundColor3 = Color3.fromRGB(164, 139, 255),
        BorderSizePixel = 0,
    }, track)
    round(fill, 4)
    text("INITIALIZATION / VexHUB 2.1.1", 24, 192, 260, 16, 10,
        Color3.fromRGB(110, 123, 153))
    closeButton = make("TextButton", {
        Position = UDim2.fromOffset(286, 188),
        Size = UDim2.fromOffset(70, 26),
        BackgroundColor3 = Color3.fromRGB(59, 39, 57),
        BorderSizePixel = 0,
        Text = "Close",
        TextColor3 = Color3.fromRGB(255, 201, 207),
        Font = Enum.Font.Gotham,
        TextSize = 12,
        Visible = false,
    }, group)
    round(closeButton, 6)
    closeButton.Activated:Connect(cleanup)

    local function stage(value, message)
        status.Text = message
        percent.Text = tostring(math.floor(value)) .. "%"
        if progressTween then progressTween:Cancel() end
        progressTween = TweenService:Create(fill, TweenInfo.new(0.12),
            {Size = UDim2.fromScale(math.clamp(value / 100, 0, 1), 1)})
        progressTween:Play()
        task.wait()
    end

    stage(10, "Checking runtime support...")
    assert(type(loadstring) == "function", "This executor has no loadstring.")
    assert(type(bit32) == "table" and type(bit32.bxor) == "function",
        "This executor has no bit32.bxor.")
    assert(#payload % 2 == 0, "The script package is incomplete.")

    stage(20, "Decoding package...")
    local bytes = {}
    for i = 1, #payload, 2 do
        bytes[#bytes + 1] = string.char(
            bit32.bxor(assert(tonumber(payload:sub(i, i + 1), 16),
                "Invalid package data."), 73))
        if i % 8192 == 1 then
            stage(20 + 55 * (i / #payload), "Decoding package...")
        end
    end
    stage(80, "Compiling interface...")
    local run, compileError = loadstring(table.concat(bytes))
    bytes = nil
    assert(run, compileError)
    stage(92, "Starting VexHUB...")
    run()
    stage(100, "Ready. Enter your access key.")
    task.wait(0.25)
    local fade = TweenService:Create(group, TweenInfo.new(0.2),
        {GroupTransparency = 1})
    fade:Play()
    fade.Completed:Wait()
    cleanup()
end)

if not ok then
    env.VexHUB_BootRunning = false
    warn("[VexHUB Startup] " .. tostring(failure))
    if type(env.CB_Cleanup) == "function" then pcall(env.CB_Cleanup) end
    if status and closeButton then
        if progressTween then progressTween:Cancel() end
        status.Text = "Startup failed. Check the executor console."
        status.TextColor3 = Color3.fromRGB(255, 150, 154)
        percent.Text = "ERROR"
        closeButton.Visible = true
    else
        cleanup()
    end
end
